\\n53 | \\r\\n54 |     ToolRegistry.register([\\r\\n55 |         new BashTool(),\\r\\n56 |         new GlobTool(),\\r\\n57 |         new GrepTool(),\\r\\n58 |         new ReadFileTool(),\\r\\n59 |         new WriteFileTool(),\\r\\n60 |         new SurgicalEditTool(),\\r\\n61 |         new BatchReplaceTool(),\\r\\n62 |         new WebSearchTool(),\\r\\n63 |         new WebFetchTool(),\\r\\n64 |         new SkillTool(),\\r\\n65 |         // new ExploreTool(),\\r\\n66 |         // new TaskTool(),\\r\\n67 |         ...TodoTools(),\\r\\n68 |     ]);\\r\\n69 | }\\r\\n70 | \\r\\n71 | /**\\r\\n72 |  * 初始化并注册所有工具（包括 MCP 服务器工具）\\r\\n73 |  *\\r\\n74 |  * 在应用启动时调用此函数，异步加载 MCP 服务器\\r\\n75 |  *\\r\\n76 |  * @param configPath - MCP 配置文件路径（可选）\\r\\n77 |  * @returns MCP 管理器实例\\r\\n78 |  *\\r\\n79 |  * @example\\r\\n80 |  * ```ts\\r\\n81 |  * import { registerDefaultToolsAsync } from './tool';\\r\\n82 |  *\\r\\n83 |  * // 使用默认配置路径\\r\\n84 |  * await registerDefaultToolsAsync();\\r\\n85 |  *\\r\\n86 |  * // 或指定配置文件路径\\r\\n87 |  * await registerDefaultToolsAsync('./my-mcp-config.json');\\r\\n88 |  * ```\\r\\n89 |  */\\r\\n90 | export async function registerDefaultToolsAsync(configPath?: string) {\\r\\n91 |     // 初始化技能加载器（在注册 SkillTool 之前）\\r\\n92 |     try {\\r\\n93 |         await initializeSkills();\\r\\n94 |     } catch (error) {\\r\\n95 |         console.warn('[Skills] Failed to initialize skills:', error);\\r\\n96 |     }\\r\\n97 | \\r\\n98 |     // 注册内置工具\\r\\n99 |     registerDefaultTools();\\r\\n100 | \\r\\n101 |     // 初始化 MCP 服务器（如果配置文件存在）\\r\\n102 |     try {\\r\\n103 |         const manager = await initializeMcp(configPath);\\r\\n104 |         const servers = manager.getConnectedServers();\\r\\n105 |         const totalTools = manager.getTotalToolsCount();\\r\\n106 | \\r\\n107 |         if (servers.length > 0) {\\r\\n108 |             console.log(`[MCP] Loaded ${totalTools} tools from ${servers.length} server(s)`);\\r\\n109 |         }\\r\\n110 | \\r\\n111 |         return