343 |   "content": "{\n  \"filePath\": \"src/session-v2/compaction.ts\",\n  \"content\": \"1 | import { Message, LLMProvider } from \\\"../providers/base\\\";\\n2 | import { OpenAIProvider } from \\\"../providers/openai\\\";\\n3 | import { ScopedLogger } from \\\"../util/log\\\";\\n4 | \\n5 | export class Compaction {\\n6 |   private readonly maxTokens: number;\\n7 |   private readonly maxOutputTokens: number;\\n8 |   private readonly triggerRatio = 0.92; // 92% 触发压缩\\n9 |   private keepMessagesNum: number = 40;\\n10 |   logger: ScopedLogger;\\n11 |   llmProvider: LLMProvider;\\n12 | \\n13 |   constructor(config: { maxTokens: number; maxOutputTokens: number; llmProvider: LLMProvider; keepMessagesNum?: number }) {\\n14 |     this.maxTokens = config.maxTokens;\\n15 |     this.maxOutputTokens = config.maxOutputTokens;\\n16 |     this.logger = new ScopedLogger(\\\"Compaction\\\");\\n17 |     this.llmProvider = config.llmProvider;\\n18 |     this.keepMessagesNum = config.keepMessagesNum || this.keepMessagesNum;\\n19 |   }\\n20 | \\n21 |   getToken(history: Message[]) {\\n22 |     const totalUsed = this.calculateTotalUsage(history);\\n23 |     const usableLimit = this.maxTokens - this.maxOutputTokens;\\n24 | \\n25 |     return {\\n26 |       totalUsed,\\n27 |       usableLimit: usableLimit * this.triggerRatio\\n28 |     };\\n29 |   }\\n30 | \\n31 |   /**\\n32 |    * 性能优化：构建 tool_call_id 到 assistant 索引的映射表\\n33 |    * 时间复杂度：O(n)，其中 n 是 history 的长度\\n34 |    * @returns Map<tool_call_id, assistant_index>\\n35 |    */\\n36 |   private buildToolCallToAssistantIndex(messages: Message[]): Map<string, number> {\\n37 |     const index = new Map<string, number>();\\n38 | \\n39 |     // 遍历所有消息，记录每个 tool_call_id 对应的 assistant 索引\\n40 |     for (let i = 0; i < messages.length; i++) {\\n41 |       const msg = messages[i];\\n42 |       if (msg.role === 'assistant' && msg.tool_calls) {\\n43 |         for (const call of msg.tool_calls) {\\n44 |           if (call.id) {\\n45 |             index.set(call.id, i);\\n46 |           }\\n47 |         }\\n48 |       }\\n49 |     }\\n50 | \\n51 |     return index;\\n52 |   }\\n53 | \\n54 |   /**\\n55 |    * 性能优化：构建消息列表中 tool 消息的索引映射\\n56 |    * 时间复杂度：O(m)，其中 m 是 messages 的长度\\n57 |    * @returns Map<tool_call_id, message>\\n58 |    */\\n59 |   private buildToolMessageMap(messages: Message[]): Map<string, Message> {\\n60 |     const map = new Map<string, Message>();\\n61 | \\n62 |     for (const msg of messages) {\\n63 |       if (msg.role === 'tool' && msg.tool_call_id) {\\n64 |         map.set(msg.tool_call_id, msg);\\n65 |       }\\n66 |     }\\n67 | \\n68 |     return map;\\n69 |   }\\n70 | \\n71 |   async compact(history: Message[]): Promise<{\\n72 |     isCompacted: boolean,\\n73 |     summaryMessage: Message | null,\\n74 |     list: Message[]\\n75 |   }> {\\n76 |     const totalUsed = this.calculateTotalUsage(history);\\n77 |     const usableLimit = this.maxTokens - this.maxOutputTokens;\\n78 |     const threshold = usableLimit * this.triggerRatio;\\n79 | \\n80 |     // 只有当消息数量超过保留数量且 token 达到阈值时，才触发压缩\\n81 |     const shouldCompact = history.length > this.keepMessagesNum && totalUsed >= threshold;\\n82 | \\n83 |     // 如果没达到压缩条件，直接返回原数据\\n84 |     if (!shouldCompact) {\\n85 |       return {\\n86 |         isCompacted: false,\\n87 |         summaryMessage: null,\\n88 |         list: history\\n89 |       };\\n90 |     }\\n91 | \\n92 |     this.logger.info(\\n93 |       `[Compaction] 触发压缩。当前 Token: ${totalUsed}, 阈值: ${Math.floor(threshold)}`\\n94 |     );\\n95 | \\n96 |     let activeMessages = history.slice(-this.keepMessagesNum); // 保护区\\n97 |     let pendingMessages = history.slice(0, -this.keepMessagesNum); // 待压缩区\\n98 | \\n99 |     // 限制保护区的最大膨胀倍数（防止从 6 条膨胀到 100+ 条）\\n100 |     const MAX_ACTIVE_SIZE = this.keepMessagesNum * 2;\\n101 | \\n102 |     // 检查保护区的所有 tool 消息，确保它们的配对 assistant 以及所有相关的 tool 回复都被保留\\n103 |     // 需要处理多个 assistant 的情况（连续多次工具调用）\\n104 | \\n105 |     // 性能优化：一次性构建所有索引，避免 O(n²) 的多次查找\\n106 |     // 时间复杂度：O(n + m + k)，其中 n=history长度，m=pending长度，k=active长度\\n107 |     const toolCallToAssistantIndex = this.buildToolCallToAssistantIndex(history);\\n108 |     const pendingToolMap = this.buildToolMessageMap(pendingMessages);\\n109 |     const activeToolMap = this.buildToolMessageMap(activeMessages);\\n110 | \\n111 |     const toolMessagesInActive = activeMessages.filter(m =>\\n112 |       m.role === 'tool' && m.tool_call_id  // 过滤掉无效的 tool_call_id\\n113 |     );\\n114 | \\n115 |     if (toolMessagesInActive.length > 0) {\\n116 |       // 收集所有需要保留的 assistant 消息和需要重新排序的 tool 回复\\n117 |       // 修复：将 tool 回复与对应的 assistant 分组，确保消息顺序正确\\n118 |       const assistantsToKeep: Map<string, { message: Message; index: number; tools: Message[] }> = new Map();\\n119 |       // 跟踪从 pendingMessages 移到 toolsToKeep 的 tool_call_id\\n120 |       const movedToolCallIds = new Set<string>();\\n121 | \\n122 |       // 计算分割点，用于判断 assistant 在哪个区域\\n123 |       // history[:splitPoint] = pendingMessages\\n124 |       // history[splitPoint:] = activeMessages\\n125 |       const splitPoint = history.length - this.keepMessagesNum;\\n126 | \\n127 |       // 修复：识别唯一需要处理的 assistant 索引\\n128 |       // 这确保我们只处理每个 assistant 一次，但会收集该 assistant 的所有 tools\\n129 |       const uniqueAssistantIndices = new Set<number>();\\n130 |       for (const toolMessage of toolMessagesInActive) {\\n131 |         const toolCallId = toolMessage.tool_call_id;\\n132 |         if (!toolCallId) continue;\\n133 |         const assistantIndex = toolCallToAssistantIndex.get(toolCallId);\\n134 |         if (assistantIndex !== undefined) {\\n135 |           uniqueAssistantIndices.add(assistantIndex);\\n136 |         }\\n137 |       }\\n138 | \\n139 |       // 为每个唯一的 assistant 处理一次，收集其所有 tools\\n140 |       for (const assistantIndex of uniqueAssistantIndices) {\\n141 |         // 从 history 中获取 assistant 消息\\n142 |         const assistantMessage = history[assistantIndex];\\n143 |         if (!assistantMessage || !assistantMessage.tool_calls || assistantMessage.tool_calls.length === 0) {\\n144 |           continue;\\n145 |         }\\n146 | \\n147 |         const assistantKey = assistantIndex.toString();\\n148 |         const toolCalls = assistantMessage.tool_calls?.filter(call => call.id) || [];\\n149 | \\n150 |         // 收集该 assistant 的所有 tools（从两个区域按 tool_calls 顺序收集）\\n151 |         const allTools: Message[] = [];\\n152 |         for (const toolCall of toolCalls) {\\n153 |           // 先检查 active 区域，再检查 pending 区域\\n154 |           let toolMessage = activeToolMap.get(toolCall.id);\\n155 |           if (!toolMessage) {\\n156 |             toolMessage = pendingToolMap.get(toolCall.id);\\n157 |             if (toolMessage) {\\n158 |               movedToolCallIds.add(toolCall.id); // 跟踪从 pending 移动的 tool\\n159 |             }\\n160 |           }\\n161 |           if (toolMessage) {\\n162 |             allTools.push(toolMessage);\\n163 |           }\\n164 |         }\\n165 | \\n166 |         const toolCallIds = toolCalls.map(c => c.id);\\n167 | \\n168 |         // 无论 assistant 在哪个区域，都从 activeMessages 中移除它的 tools（稍后会重新添加）\\n169 |         // 这避免 tools 在 activeMessages 中被重复计算\\n170 |         activeMessages = activeMessages.filter(m => {\\n171 |           // 如果 assistant 在 active 区域，也要移除它\\n172 |           if (assistantIndex >= splitPoint && m === assistantMessage) return false;\\n173 |           // 移除这些 tool 回复（无论 assistant 在哪，都要移除 active 中的 tools）\\n174 |           if (m.role === 'tool' && toolCallIds.includes(m.tool_call_id || '')) return false;\\n175 |           return true;\\n176 |         });\\n177 | \\n178 |         // 记录这个 assistant 需要保留，以及它的所有 tools\\n179 |         assistantsToKeep.set(assistantKey, {\\n180 |           message: assistantMessage,\\n181 |           index: assistantIndex,\\n182 |           tools: allTools,\\n183 |         });\\n184 | \\n185 |         this.logger.info(\\n186 |           `[Compaction] 处理 assistant（索引 ${assistantIndex}）：` +\\n187 |           `${toolCalls.length} 个 tool_calls，收集到 ${allTools.length} 个 tool 回复`\\n188 |         );\\n189 |       }\\n190 | \\n191 |       // 将需要保留的 assistant 和 tool 回复按正确顺序加入保护区\\n192 |       if (assistantsToKeep.size > 0) {\\n193 |         // 按索引排序 assistants（保持原始顺序）\\n194 |         const sortedAssistantsWithTools = Array.from(assistantsToKeep.values())\\n195 |           .sort((a, b) => a.index - b.index);\\n196 | \\n197 |         // 从 pendingMessages 中移除这些 assistants（如果它们在 pendingMessages 中）\\n198 |         // 同时移除已移动的 tool 消息\\n199 |         // 修复：使用 splitPoint 而不是 pendingMessages.length\\n200 |         // item.index 是原 history 数组的索引，需要与 splitPoint 比较\\n201 |         const indicesToRemove = Array.from(assistantsToKeep.values())\\n202 |           .filter(item => item.index < splitPoint)\\n203 |           .map(item => item.index);\\n204 | \\n205 |         if (indicesToRemove.length > 0 || movedToolCallIds.size > 0) {\\n206 |           pendingMessages = pendingMessages.filter((msg, i) => {\\n207 |             // 移除 assistant 消息\\n208 |             if (indicesToRemove.includes(i)) return false;\\n209 |             // 移除已移动的 tool 消息\\n210 |             if (msg.role === 'tool' && msg.tool_call_id && movedToolCallIds.has(msg.tool_call_id)) return false;\\n211 |             return true;\\n212 |           });\\n213 |         }\\n214 | \\n215 |         // 构建新的 activeMessages，将每个 assistant 与它的 tools 交错排列\\n216 |         // 正确的结构应该是：Assistant1, Tool1, Tool2, Assistant2, Tool3, Tool4, ...\\n217 |         const newActiveMessages: Message[] = [];\\n218 | \\n219 |         for (const { message: assistantMsg, tools: assistantTools } of sortedAssistantsWithTools) {\\n220 |           newActiveMessages.push(assistantMsg);\\n221 |           newActiveMessages.push(...assistantTools);\\n222 |         }\\n223 | \\n224 |         // 添加剩余的 activeMessages\\n225 |         newActiveMessages.push(...activeMessages);\\n226 | \\n227 |         // 检查是否超过最大限制\\n228 |         if (newActiveMessages.length > MAX_A