tion',\\r\\n376 |             function: {\\r\\n377 |               name: existing?.function.name || toolCall.function.name || '',\\r\\n378 |               arguments: (existing?.function.arguments || '') + (toolCall.function.arguments || ''),\\r\\n379 |             },\\r\\n380 |           });\\r\\n381 |         },\\r\\n382 |         onFinish: (reason) => {\\r\\n383 |           finishReason = reason;\\r\\n384 |         },\\r\\n385 |       });\\r\\n386 |     } catch (error) {\\r\\n387 |       console.error('Stream processing error:', error);\\r\\n388 |       // 重新抛出异常，让上层 Agent 处理\\r\\n389 |       throw error;\\r\\n390 |     }\\r\\n391 | \\r\\n392 |     return {\\r\\n393 |       content: accumulatedContent,\\r\\n394 |       role: 'assistant',\\r\\n395 |       type: 'text',\\r\\n396 |       tool_calls: toolCallsMap.size > 0 ? [...toolCallsMap.values()] : undefined,\\r\\n397 |       usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },\\r\\n398 |       finishReason,\\r\\n399 |     };\\r\\n400 |   }\\r\\n401 | \\r\\n402 |   private async processStream(\\r\\n403 |     reader: ReadableStreamDefaultReader,\\r\\n404 |     decoder: typeof TextDecoder.prototype,\\r\\n405 |     handlers: {\\r\\n406 |       onContent: (content: string) => void;\\r\\n407 |       onToolCall: (tc: { index: number; id?: string; type?: string; function: { name?: string; arguments?: string } }) => void;\\r\\n408 |       onFinish: (reason: string | undefined) => void;\\r\\n409 |     }\\r\\n410 |   ): Promise<void> {\\r\\n411 |     let buffer = '';\\r\\n412 |     let shouldStop = false;\\r\\n413 | \\r\\n414 |     while (!shouldStop) {\\r\\n415 |       const { done, value } = await reader.read();\\r\\n416 |  \\r\\n417 |       if (done) break;\\r\\n418 | \\r\\n419 |       buffer += decoder.decode(value, { stream: true });\\r\\n420 |       const lines = buffer.split(/[\\\\r\\\\n]+/);\\r\\n421 |       buffer = lines.pop() || '';\\r\\n422 | \\r\\n423 |       for (const line of lines) {\\r\\n424 