501 |   "content": "{\n  \"filePath\": \"src/tool/bash.ts\",\n  \"content\": \"1 | /**\\r\\n2 |  * Bash Tool\\r\\n3 |  *\\r\\n4 |  * 执行 bash 命令的工具，提供：\\r\\n5 |  * - 语法验证和解析\\r\\n6 |  * - 安全分析\\r\\n7 |  * - 命令执行\\r\\n8 |  */\\r\\n9 | \\r\\n10 | import { BaseTool, ToolResult } from './base';\\r\\n11 | import { z } from 'zod';\\r\\n12 | import { getBashParser } from './bash-parser';\\r\\n13 | import { getPlatform, execCommandAsync } from '../util/platform-cmd';\\r\\n14 | \\r\\n15 | // =============================================================================\\r\\n16 | // 模式定义\\r\\n17 | // =============================================================================\\r\\n18 | \\r\\n19 | const scriptLanguages = ['node', 'python', 'python3'] as const;\\r\\n20 | type ScriptLanguage = typeof scriptLanguages[number];\\r\\n21 | \\r\\n22 | const schema = z.object({\\r\\n23 |     command: z.string().min(1).describe('The bash command to run').optional(),\\r\\n24 |     language: z.enum(scriptLanguages).describe('Inline script language (node/python)').optional(),\\r\\n25 |     code: z.string().min(1).describe('Inline script to execute').optional(),\\r\\n26 |     args: z.array(z.string()).describe('Arguments for inline scripts').optional(),\\r\\n27 |     stdin: z.string().describe('Optional stdin for the command').optional(),\\r\\n28 | });\\r\\n29 | \\r\\n30 | // =============================================================================\\r\\n31 | // BashTool 类\\r\\n32 | // =============================================================================\\r\\n33 | \\r\\n34 | export default class BashTool extends BaseTool<typeof schema> {\\r\\n35 |     name = 'bash';\\r\\n36 |     private cwd = process.cwd();\\r\\n37 | \\r\\n38 |     get description(): string {\\r\\n39 |         return 'Run bash commands, with optional inline node/python scripts';\\r\\n40 |     }\\r\\n41 | \\r\\n42 |     schema = schema;\\r\\n43 | \\r\\n44 |     /** 命令执行超时时间（毫秒），默认 60 秒 */\\r\\n45 |     timeout: number = 60000;\\r\\n46 | \\r\\n47 |     /**\\r\\n48 |      * 执行 bash 命令\\r\\n49 |      *\\r\\n50 |      * 错误分类：\\r\\n51 |      * - 业务错误（参数验证、安全检查）→ return this.fail()\\r\\n52 |      * - 底层异常（执行失败）→ throw 供 Registry 捕获\\r\\n53 |      */\\r\\n54 |     async execute(args: z.infer<typeof this.schema>): Promise<ToolResult> {\\r\\n55 |         const { command, language, code, args: scriptArgs, stdin } = args;\\r\\n56 | \\r\\n57 |         // === 业务错误：参数验证 ===\\r\\n58 |         const validationError = this.validateArgs({ command, language, code, args: scriptArgs, stdin });\\r\\n59 |         if (validationError) {\\r\\n60 |             return this.fail(validationError, { code: 'VALIDATION_ERROR' });\\r\\n61 |         }\\r\\n62 | \\r\\n63 |         const hasCode = Boolean(code?.trim());\\r\\n64 |         const execution = hasCode\\r\\n65 |             ? { command: this.buildInlineCommand(language as ScriptLanguage, scriptArgs), input: code }\\r\\n66 |             : { command: command as string, input: stdin };\\r\\n67 | \\r\\n68 |         // === 业务错误：语法检查 ===\\r\\n69 |         const platform = getPlatform();\\r\\n70 |         if (platform !== 'windows') {\\r\\n71 |             const parser = await getBashParser();\\r\\n72 |             const parseResult = parser.parse(execution.command);\\r\\n73 |             if (!parseResult.valid) {\\r\\n74 |                 return this.fail(\\r\\n75 |                     'Command not executed due to syntax error',\\r\\n76 |                     { code: 'SYNTAX_ERROR', details: parseResult.error }\\r\\n77 |                 );\\r\\n78 |             }\\r\\n79 |         } else {\\r\\n80 |             const dangerousPattern = /(^|\\\\s)(format|shutdown|reg\\\\s+delete|rmdir\\\\s+\\\\/s|rd\\\\s+\\\\/s|del\\\\s+\\\\/f)(\\\\s|$)/i;\\r\\n81 |             if (dangerousPattern.test(execution.command)) {\\r\\n82 |                 return this.fail(\\r\\n83 |                     'Command not executed due to safety policy',\\r\\n84 |                     { code: 'SAFETY_POLICY_VIOLATION' }\\r\\n85 |                 );\\r\\n86 |             }\\r\\n87 |         }\\r\\n88 | \\r\\n89 |         // === 执行命令 ===\\r\\n90 |         const result = await this.runCommand(execution.command, execution.input);\\r\\n91 |         return result;\\r\\n92 |     }\\r\\n93 | \\r\\n94 |     /**\\r\\n95 |      * 执行 bash 命令\\r\\n96 |      *\\r\\n97 |      * 错误分类：\\r\\n98 |      * - cd 解析失败 → return fail()（业务错误）\\r\\n99 |      * - 命令执行异常 → throw（底层异常）\\r\\n100 |      */\\r\\n101 |     private async runCommand(command: string, input?: string): Promise<ToolResult> {\\r\\n102 |         // 处理 cd 命令（业务错误）\\r\\n103 |         const cdError = this.tryHandleCd(command);\\r\\n104 |         if (cdError) {\\r\\n105 |             return this.fail(`Command failed: ${cdError}`, { code: 'CD_FAILED' });\\r\\n106 |         }\\r\\n107 | \\r\\n108 |         const normalizedCommand = this.normalizeCommand(command);\\r\\n109 | \\r\\n110 |         try {\\r\\n111 |             // === 底层异常：命令执行 ===\\r\\n112 |             const result = await execCommandAsync(normalizedCommand, {\\r\\n113 |                 timeout: this.timeout,\\r\\n114 |                 cwd: this.cwd,\\r\\n115 |                 input,\\r\\n116 |             });\\r\\n117 | \\r\\n118 |             if (result.exitCode === 0) {\\r\\n119 |                 return this.success(\\r\\n120 |                     { output: result.stdout || 'Command exited successfully' },\\r\\n121 |                     { truncated: result.stdout.length > 12000 }\\r\\n122 |                 );\\r\\n123 |             } else {\\r\\n124 |                 return this.fail(\\r\\n125 |                     result.stderr || `Command failed with exit code ${result.exitCode}`,\\r\\n126 |                     { code: 'COMMAND_FAILED', exitCode: result.exitCode }\\r\\n127 |                 );\\r\\n128 |             }\\r\\n129 |         } catch (error) {\\r\\n130 |             // 底层异常，让 Registry 统一捕获\\r\\n131 |             throw new Error(`Fail