   }\\r\\n174 | \\r\\n175 |         const { tokens, quoteTypes } = this.tokenize(command);\\r\\n176 |         const normalizedTokens = tokens.map((token, i) => {\\r\\n177 |             const quote = quoteTypes[i];\\r\\n178 |             const original = quote ? `${quote}${token}${quote}` : token;\\r\\n179 |             if (!token.includes('/')) return original;\\r\\n180 |             if (token.startsWith('/')) return original;\\r\\n181 |             if (token.includes('://')) return original;\\r\\n182 | \\r\\n183 |             const looksLikeProjectPath =\\r\\n184 |                 token.startsWith('./') ||\\r\\n185 |                 token.startsWith('../') ||\\r\\n186 |                 token.startsWith('src/') ||\\r\\n187 |                 token.startsWith('test/') ||\\r\\n188 |                 token.startsWith('__tests__/') ||\\r\\n189 |                 /\\\\.(ts|tsx|js|jsx|json|md|txt|log|env)$/i.test(token) ||\\r\\n190 |                 token.includes('/src/') ||\\r\\n191 |                 token.includes('/test/') ||\\r\\n192 |                 token.includes('/__tests__/');\\r\\n193 | \\r\\n194 |             if (!looksLikeProjectPath) return original;\\r\\n195 | \\r\\n196 |             const replaced = token.replace(/\\\\//g, '\\\\\\\\');\\r\\n197 |             return quote ? `${quote}${replaced}${quote}` : replaced;\\r\\n198 |         });\\r\\n199 | \\r\\n200 |         return normalizedTokens.join(' ');\\r\\n201 |     }\\r\\n202 | \\r\\n203 |     private tokenize(command: string): { tokens: string[]; quoteTypes: Array<'\\\"' | \\\"'\\\" | null> } {\\r\\n204 |         const tokens: string[] = [];\\r\\n205 |         const quoteTypes: Array<'\\\"' | \\\"'\\\" | null> = [];\\r\\n206 |         let current = '';\\r\\n207 |         let quote: '\\\"' | \\\"'\\\" | null = null;\\r\\n208 | \\r\\n209 |         for (let i = 0; i < command.length; i++) {\\r\\n210 |             const ch = command[i];\\r\\n211 |             if ((ch === '\\\"' || ch === \\\"'\\\") && quote ===