Events extends Record<string, any>> {\\n532 |   private bus = new EventBus();\\n533 | \\n534 |   on<TEvent extends keyof TEvents>(\\n535 |     event: TEvent,\\n536 |     handler: EventHandler<TEvents[TEvent]>,\\n537 |     handlerId?: string\\n538 |   ): Subscription {\\n539 |     return this.bus.on(event as string, handler, handlerId);\\n540 |   }\\n541 | \\n542 |   onAsync<TEvent extends keyof TEvents>(\\n543 |     event: TEvent,\\n544 |     handler: AsyncEventHandler<TEvents[TEvent]>,\\n545 |     handlerId?: string\\n546 |   ): Subscription {\\n547 |     return this.bus.onAsync(event as string, handler, handlerId);\\n548 |   }\\n549 | \\n550 |   once<TEvent extends keyof TEvents>(\\n551 |     event: TEvent,\\n552 |     handler: EventHandler<TEvents[TEvent]>\\n553 |   ): Subscription {\\n554 |     return this.bus.once(event as string, handler);\\n555 |   }\\n556 | \\n557 |   onceAsync<TEvent extends keyof TEvents>(\\n558 |     event: TEvent,\\n559 |     handler: AsyncEventHandler<TEvents[TEvent]>\\n560 |   ): Subscription {\\n561 |     return this.bus.onceAsync(event as string, handler);\\n562 |   }\\n563 | \\n564 |   async emit<TEvent extends keyof TEvents>(\\n565 |     event: TEvent,\\n566 |     data: TEvents[TEvent],\\n567 |     metadata?: Partial<EventMetadata>\\n568 |   ): Promise<void> {\\n569 |     return this.bus.emit(event as string, data, metadata);\\n570 |   }\\n571 | \\n572 |   off<TEvent extends keyof TEvents>(event: TEvent, handlerId: string): boolean {\\n573 |     return this.bus.off(event as string, handlerId);\\n574 |   }\\n575 | \\n576 |   offAll(event?: keyof TEvents): void {\\n577 |     this.bus.offAll(event as string);\\n578 |   }\\n579 | \\n580 |   use(middleware: Middleware): void {\\n581 |     this.bus.use(middleware);\\n582 |   }\\n583 | \\n584 |   useForEvent<TEvent extends keyof TEvents>(event: TEvent, middleware: Middleware<TEvents[TEvent]>): void {\\n585 |     this.bus.useForEvent(event as string, middleware);\\n586 |   }\\n587 | \\n588 |   listenerCount(event?: keyof TEvents): number {\\n589 |     return this.bus.listenerCount(event as string);\\n590 |   }\\n591 | \\n592 |   eventNames(): string[] {\\n593 |     return this.bus.eventNames();\\n594 |   }\\n595 | \\n596 |   getMetrics(event?: keyof TEvents): EventMetrics | Map<string, EventMetrics> {\\n597 |     return this.bus.getMetrics(event as string);\\n598 |   }\\n599 | \\n600 |   resetMetrics(event?: keyof TEvents): void {\\n601 |     this.bus.resetMetrics(event as string);\\n602 |   }\\n603 | \\n604 |   createScopedBus(scope: string): ScopedEventBus {\\n605 |     return this.bus.createScopedBus(scope);\\n606 |   }\\n607 | \\n608 |   waitFor<TEvent extends keyof TEvents>(\\n609 |     event: TEvent,\\n610 |     timeout?: number\\n611 |   ): Promise<TEvents[TEvent]> {\\n612 |     return this.bus.waitFor(event as string, timeout);\\n613 |   }\\n614 | }\\n615 | \\n616 | /**\\n617 |  * 默认导出单例实例\\n618 |  */\\n619 | export const eventBus = new EventBus({\\n620 |   maxListeners: 100,\\n621 |   enableAsync: true,\\n622 |   defaultTimeout: 10000,\\n623 |   enableMetrics: true,\\n624 | });\\n625 | \\n626 | /**\\n627 |  * 类型安全的单例实例\\n628 |  */\\n629 | export const typedEventBus = new TypedEventBus<SessionEvents & AgentEvents>();\\n630 | \\n631 | /**\\n632 |  * 工具函数：创建日志中间件\\n633 |  */\\n634 | export function createLoggingMiddleware(source?: string): Middleware {\\n635 |   return async (context, next) => {\\n636 |     const startTime = Date.now();\\n637 |     console.log(`[${source || 'EventBus'}] Event started: ${context.event}`, {\\n638 |       correlationId: context.metadata.correlationId,\\n639 |       timestamp: new Date(context.metadata.timestamp).toISOString(),\\n640 |     });\\n641 | \\n642 |     try {\\n643 |       await next();\\n644 |       const duration = Date.now() - startTime;\\n645 |       console.log(`[${source || 'EventBus'}] Event completed: ${context.event}`, {\\n646 |         correlationId: context.metadata.correlationId,\\n647 |         duration: `${duration}ms`,\\n648 |       });\\n649 |     } catch (error) {\\n650 |       const duration = Date.now() - startTime;\\n651 |       console.error(`[${source || 'EventBus'}] Event failed: ${context.event}`, {\\n652 |         correlationId: context.metadata.correlationId,\\n653 |         duration: `${duration}ms`,\\n654 |         error,\\n655 |       });\\n656 |       throw error;\\n657 |     }\\n658 |   };\\n659 | }\\n660 | \\n661 | /**\\n662 |  * 工具函数：创建错误处理中间件\\n663 |  */\\n664 | export function createErrorHandlingMiddleware(\\n665 |   onError?: (error: Error, context: EventContext) => void\\n666 | ): Middleware {\\n667 |   return async (context, next) => {\\n668 |     try {\\n669 |       await next();\\n670 |     } catch (error) {\\n671 |       if (onError) {\\n672 |         onError(error instanceof Error ? error : new Error(String(error)), context);\\n673 |       }\\n674 |       throw error;\\n675 |     }\\n676 |   };\\n677 | }\\n678 | \\n679 | /**\\n680 |  * 工具函数：创建验证中间件\\n681 |  */\\n682 | export function createValidationMiddleware<T>(\\n683 |   validator: (data: T) => boolean | Promise<boolean>,\\n684 |   errorMessage = 'Validation failed'\\n685 | ): Middleware<T> {\\n686 |   return async (context, next) => {\\n687 |     const isValid = await validator(context.data);\\n688 |     if (!isValid) {\\n689 |       throw new Error(`${errorMessage} for event: ${context.event}`);\\n690 |     }\\n691 |     await next();\\n692 |   };\\n693 | }\",\n  \"range\": {\n    \"startLine\": 1,\n    \"endLine\": 693\n  }\n}",
