r\\n176 |   }\\r\\n177 | \\r\\n178 |   /**\\r\\n179 |    * 输出成功信息\\r\\n180 |    * 使用场景：任务完成、构建成功、数据同步完成、阶段性里程碑。\\r\\n181 |    * @param msg 字符串或对象\\r\\n182 |    * @param scope 作用域名称（可选）\\r\\n183 |    */\\r\\n184 |   static success(msg: unknown, scope?: string) {\\r\\n185 |     if (!enabled(this.level, 'info')) return;\\r\\n186 |     const p = `[${now()}] [SUCCESS]`;\\r\\n187 |     console.log(`${chalk.green(p)}${scope ? ` [${scope}]` : ''} ${chalk.green(stringify(msg))}`);\\r\\n188 |   }\\r\\n189 | \\r\\n190 |   /**\\r\\n191 |    * 输出调试信息（仅在debug级别显示）\\r\\n192 |    * 使用场景：开发诊断、性能测量、参数与上下文细节。\\r\\n193 |    * @param msg 字符串或对象\\r\\n194 |    * @param scope 作用域名称（可选）\\r\\n195 |    */\\r\\n196 |   static debug(msg: unknown, scope?: string) {\\r\\n197 |     if (!enabled(this.level, 'debug')) return;\\r\\n198 |     console.debug(`${prefix('debug', scope)} ${chalk.gray(stringify(msg))}`);\\r\\n199 |   }\\r\\n200 | \\r\\n201 |   /**\\r\\n202 |    * 结构化输出对象/JSON\\r\\n203 |    * 使用场景：接口返回、配置快照、调试上下文、状态采样。\\r\\n204 |    * @param obj 任意对象（自动JSON格式化）\\r\\n205 |    * @param label 可选标签，便于快速定位\\r\\n206 |    * @param scope 作用域名称（可选）\\r\\n207 |    */\\r\\n208 |   static json(obj: unknown, label?: string, scope?: string) {\\r\\n209 |     const body = stringify(obj);\\r\\n210 |     const head = label ? `${label}:` : '';\\r\\n211 |     if (enabled(this.level, 'info')) {\\r\\n212 |       console.log(`${prefix('info', scope)} ${chalk.white(head)}\\\\n${body}`);\\r\\n213 |     }\\r\\n214 |   }\\r\\n215 | \\r\\n216 |   /**\\r\\n217 |    * 创建指定作用域的日志器\\r\\n218 |    * 使用场景：为模块/子系统分配独立前缀，便于定位日志来源。\\r\\n219 |    * @param name 作用域名称\\r\\n220 |    * @returns ScopedLogger\\r\\n221 |    */\\r\\n222 |   static scope(name: string): ScopedLogger {\\r\\n223 |     return new ScopedLogger(name);\\r\\n224 |   }\\r\\n225 | \\r\\n226 |   /**\\r\\n227 |    * 创建并启动进度Spinner\\r\\n228 |    * 使用场景：长耗时任务（拉取、构建、迁移、上传），TTY环境显示动画。\\r\\n229 |    * @param text Spinner文案\\r\\n230 |    * @param scope 作用域名称（可选）\\r\\n231 | 