2187 |   "content": "{\n  \"filePath\": \"src/util/event-bus/middleware.ts\",\n  \"content\": \"1 | /**\\n2 |  * EventBus 中间件工具函数\\n3 |  * 提供常用中间件工厂函数\\n4 |  */\\n5 | \\n6 | import type { Middleware, EventContext } from './types';\\n7 | \\n8 | /**\\n9 |  * 创建日志中间件\\n10 |  */\\n11 | export function createLoggingMiddleware(source?: string): Middleware {\\n12 |   return async (context, next) => {\\n13 |     const startTime = Date.now();\\n14 |     console.log(`[${source || 'EventBus'}] Event started: ${context.event}`, {\\n15 |       correlationId: context.metadata.correlationId,\\n16 |       timestamp: new Date(context.metadata.timestamp).toISOString(),\\n17 |     });\\n18 | \\n19 |     try {\\n20 |       await next();\\n21 |       const duration = Date.now() - startTime;\\n22 |       console.log(`[${source || 'EventBus'}] Event completed: ${context.event}`, {\\n23 |         correlationId: context.metadata.correlationId,\\n24 |         duration: `${duration}ms`,\\n25 |       });\\n26 |     } catch (error) {\\n27 |       const duration = Date.now() - startTime;\\n28 |       console.error(`[${source || 'EventBus'}] Event failed: ${context.event}`, {\\n29 |         correlationId: context.metadata.correlationId,\\n30 |         duration: `${duration}ms`,\\n31 |         error,\\n32 |       });\\n33 |       throw error;\\n34 |     }\\n35 |   };\\n36 | }\\n37 | \\n38 | /**\\n39 |  * 创建错误处理中间件\\n40 |  */\\n41 | export function createErrorHandlingMiddleware(\\n42 |   onError?: (error: Error, context: EventContext) => void\\n43 | ): Middleware {\\n44 |   return async (context, next) => {\\n45 |     try {\\n46 |       await next();\\n47 |     } catch (error) {\\n48 |       if (onError) {\\n49 |         onError(error instanceof Error ? error : new Error(String(error)), context);\\n50 |       }\\n51 |       throw error;\\n52 |     }\\n53 |   };\\n54 | }\\n55 | \\n56 | /**\\n57 |  * 创建验证中间件\\n58 |  */\\n59 | export function createValidationMiddleware<T>(\\n60 |   validator: (data: T) => boolean | Promise<boolean>,\\n61 |   errorMessage = 'Validation failed'\\n62 | ): Middleware<T> {\\n63 |   return async (context, next) => {\\n64 |     const isValid = await validator(context.data);\\n65 |     if (!isValid) {\\n66 |       throw new Error(`${errorMessage} for event: ${context.event}`);\\n67 |     }\\n68 |     await next();\\n69 |   };\\n70 | }\\n71 | \\n72 | /**\\n73 |  * 创建超时中间件\\n74 |  */\\n75 | export function createTimeoutMiddleware(timeoutMs: number): Middleware {\\n76 |   return async (context, next) => {\\n77 |     const timeout = setTimeout(() => {\\n78 |       context.abort();\\n79 |     }, timeoutMs);\\n80 | \\n81 |     try {\\n82 |       await next();\\n83 |     } finally {\\n84 |       clearTimeout(timeout);\\n85 |     }\\n86 |   };\\n87 | }\\n88 | \\n89 | /**\\n90 |  * 创建重试中间件\\n91 |  */\\n92 | export function createRetryMiddleware(\\n93 |   maxRetries: number,\\n94 |   delayMs: number = 1000\\n95 | ): Middleware {\\n96 |   return async (context, next) => {\\n97 |     let attempt = 0;\\n98 |     let lastError: Error | undefined;\\n99 | \\n100 |     while (attempt <= maxRetries) {\\n101 |       try {\\n102 |         await next();\\n103 |         return; // 成功则返回\\n104 |       } catch (error) {\\n105 |         lastError = error instanceof Error ? error : new Error(String(error));\\n106 |         attempt++;\\n107 | \\n108 |         if (attempt <= maxRetries) {\\n109 |           // 指数退避\\n110 |           const backoffMs = delayMs * Math.pow(2, attempt - 1);\\n111 |           await new Promise(resolve => setTimeout(resolve, backoffMs));\\n112 |         }\\n113 |       }\\n114 |     }\\n115 | \\n116 |     // 重试次数用完，抛出最后一次错误\\n117 |     if (lastError) {\\n118 |       throw lastError;\\n119 |     }\\n120 |   };\\n121 | }\\n122 | \",\n  \"range\": {\n    \"startLine\": 1,\n    \"endLine\": 122\n  }\n}",
