2195 |   "content": "{\n  \"filePath\": \"src/util/event-bus/TypedEventBus.ts\",\n  \"content\": \"1 | /**\\n2 |  * TypedEventBus - 类型安全的事件总线\\n3 |  * 支持强类型事件定义\\n4 |  */\\n5 | \\n6 | import type {\\n7 |   EventHandler,\\n8 |   AsyncEventHandler,\\n9 |   Subscription,\\n10 |   Middleware,\\n11 |   EventMetadata,\\n12 |   EventMetrics,\\n13 | } from './types';\\n14 | import { EventBus } from './EventBus';\\n15 | \\n16 | /**\\n17 |  * 类型安全的事件总线（泛型版本）\\n18 |  */\\n19 | export class TypedEventBus<TEvents extends Record<string, any>> {\\n20 |   private bus = new EventBus();\\n21 | \\n22 |   on<TEvent extends keyof TEvents>(\\n23 |     event: TEvent,\\n24 |     handler: EventHandler<TEvents[TEvent]>,\\n25 |     handlerId?: string\\n26 |   ): Subscription {\\n27 |     return this.bus.on(event as string, handler, handlerId);\\n28 |   }\\n29 | \\n30 |   onAsync<TEvent extends keyof TEvents>(\\n31 |     event: TEvent,\\n32 |     handler: AsyncEventHandler<TEvents[TEvent]>,\\n33 |     handlerId?: string\\n34 |   ): Subscription {\\n35 |     return this.bus.onAsync(event as string, handler, handlerId);\\n36 |   }\\n37 | \\n38 |   once<TEvent extends keyof TEvents>(\\n39 |     event: TEvent,\\n40 |     handler: EventHandler<TEvents[TEvent]>\\n41 |   ): Subscription {\\n42 |     return this.bus.once(event as string, handler);\\n43 |   }\\n44 | \\n45 |   onceAsync<TEvent extends keyof TEvents>(\\n46 |     event: TEvent,\\n47 |     handler: AsyncEventHandler<TEvents[TEvent]>\\n48 |   ): Subscription {\\n49 |     return this.bus.onceAsync(event as string, handler);\\n50 |   }\\n51 | \\n52 |   async emit<TEvent extends keyof TEvents>(\\n53 |     event: TEvent,\\n54 |     data: TEvents[TEvent],\\n55 |     metadata?: Partial<EventMetadata>\\n56 |   ): Promise<void> {\\n57 |     return this.bus.emit(event as string, data, metadata);\\n58 |   }\\n59 | \\n60 |   off<TEvent extends keyof TEvents>(event: TEvent, handlerId: string): boolean {\\n61 |     return this.bus.off(event as string, handlerId);\\n62 |   }\\n63 | \\n64 |   offAll(event?: keyof TEvents): void {\\n65 |     this.bus.offAll(event as string);\\n66 |   }\\n67 | \\n68 |   use(middleware: Middleware): void {\\n69 |     this.bus.use(middleware);\\n70 |   }\\n71 | \\n72 |   useForEvent<TEvent extends keyof TEvents>(event: TEvent, middleware: Middleware<TEvents[TEvent]>): void {\\n73 |     this.bus.useForEvent(event as string, middleware);\\n74 |   }\\n75 | \\n76 |   listenerCount(event?: keyof TEvents): number {\\n77 |     return this.bus.listenerCount(event as string);\\n78 |   }\\n79 | \\n80 |   eventNames(): string[] {\",\n  \"range\": {\n    \"startLine\": 1,\n    \"endLine\": 80\n  }\n}",
