 修复超时逻辑，确保正确的行为\\n */\\nexport function createTimeoutMiddleware(timeoutMs: number): Middleware {\\n  return async (context, next) => {\\n    let timeoutId: NodeJS.Timeout | null = null;\\n    let timedOut = false;\\n\\n    const timeout = setTimeout(() => {\\n      timedOut = true;\\n      context.abort();\\n    }, timeoutMs);\\n\\n    try {\\n      await next();\\n\\n      // 检查是否超时\\n      if (timedOut) {\\n        throw new Error(`Event \\\"${context.event}\\\" timed out after ${timeoutMs}ms`);\\n      }\\n    } finally {\\n      clearTimeout(timeout);\\n    }\\n  };\\n}\\n\\n/**\\n * 创建重试中间件\\n * 修复重试计数逻辑\\n */\\nexport function createRetryMiddleware(\\n  maxRetries: number,\\n  delayMs: number = 1000\\n): Middleware {\\n  return async (context, next) => {\\n    let attempt = 0;\\n    let lastError: Error | undefined;\\n\\n    while (attempt <= maxRetries) {\\n      try {\\n        await next();\\n        return; // 成功则返回\\n      } catch (error) {\\n        lastError = error instanceof Error ? error : new Error(String(error));\\n        attempt++;\\n\\n        // 如果还有重试机会\\n        if (attempt <= maxRetries) {\\n          // 指数退避\\n          const backoffMs = delayMs * Math.pow(2, attempt - 1);\\n          await new Promise(resolve => setTimeout(resolve, backoffMs));\\n        }\\n      }\\n    }\\n\\n    // 重试次数用完，抛出最后一次错误\\n    if (lastError) {\\n      throw lastError;\\n    }\\n  };\\n}\\n\",\"filePath\":\"src/util/event-bus/middleware.ts\"}"
